import{_ as a,o as t,c as o,a3 as r}from"./chunks/framework.B9M8MqoS.js";const p=JSON.parse('{"title":"s32 CLI","description":"","frontmatter":{},"headers":[],"relativePath":"developers/index.md","filePath":"developers/index.md"}'),s={name:"developers/index.md"};function n(d,e,i,l,c,h){return t(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="s32-cli" tabindex="-1">s32 CLI <a class="header-anchor" href="#s32-cli" aria-label="Permalink to &quot;s32 CLI&quot;">​</a></h1><p><strong>s32</strong> drives the S32 from a terminal or a script: pull and push projects, edit macros, LFOs and racks, recall snapshots, grab the screen.</p><table tabindex="0"><thead><tr><th></th><th></th></tr></thead><tbody><tr><td>CLI</td><td><code>s32</code> 1.3.44</td></tr><tr><td>Protocol</td><td>3</td></tr><tr><td>Firmware</td><td>the version in the site header</td></tr></tbody></table><p>s32 talks to the <strong>S32 Editor</strong> USB interface, the same one the <a href="https://editor.shik.tech" target="_blank" rel="noreferrer">web editor</a> uses. It is not USB MIDI and not the USB drive. Actions that only work on the panel (format, firmware update, text entry) stay on the panel.</p><p>Knob, macro, rack, device, LFO and snapshot numbers in commands count from 0. <code>macro get 4 1</code> is knob 05, macro 2 on the screen.</p><h2 id="start-here" tabindex="-1">Start here <a class="header-anchor" href="#start-here" aria-label="Permalink to &quot;Start here&quot;">​</a></h2><ol><li><a href="./getting-started">Install</a></li><li><a href="./connecting">Connect</a></li><li><a href="./examples">Examples</a></li></ol><h2 id="commands" tabindex="-1">Commands <a class="header-anchor" href="#commands" aria-label="Permalink to &quot;Commands&quot;">​</a></h2><ul><li><a href="./commands/session">Session</a>: <code>hello</code>, <code>ping</code>, <code>reset</code>, <code>job</code>, <code>schema</code></li><li><a href="./commands/projects">Projects</a>: list, pull, push, create, load, save</li><li><a href="./commands/macros">Macros</a>: modes, knob names, knob maps</li><li><a href="./commands/lfos">LFOs</a>: settings and assignments</li><li><a href="./commands/racks">Racks and devices</a></li><li><a href="./commands/extmap-meta">Maps, meta, and globals</a></li><li><a href="./commands/snapshots">Snapshots</a>: banks, morph, Arrange</li><li><a href="./commands/view">View, screen, and events</a></li></ul><p>The <a href="./protocol">USB protocol</a> page covers the interface and session for people writing their own client.</p>',10)])])}const f=a(s,[["render",n]]);export{p as __pageData,f as default};
